package com.akai.livingtv;

import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.util.TypedValue;import android.view.*;import android.widget.*;

/** Home-local controls. STOP releases audio; its last card expires after exactly thirty seconds. */
final class MiniPlayerDock extends FrameLayout {
    private final MainActivity activity;private final MediaQueue queue;private FeedRepository images;private final Handler ui=new Handler(Looper.getMainLooper());private final TextView title,state,toggle;private final ImageView cover;private final ControlGlyph toggleGlyph;final View open,stop;private MediaItem last;private boolean started,showing,hiddenByControls;private String loaded="";
    private final Runnable changed=this::render;private final Runnable expiry=this::render;
    MiniPlayerDock(MainActivity a){super(a);activity=a;queue=MediaQueue.get(a);setId(View.generateViewId());GradientDrawable panel=Glass.surface(0xBD2A3235,0x557D898E,28);panel.setColors(new int[]{0xC13B4143,0xD120272B});panel.setOrientation(GradientDrawable.Orientation.TOP_BOTTOM);setBackground(panel);setClipToOutline(true);setVisibility(GONE);
        FrameLayout head=new FrameLayout(a);head.setId(View.generateViewId());head.setFocusable(true);head.setClickable(true);head.setDefaultFocusHighlightEnabled(false);head.setBackground(focus(0x00202A2D,22));open=head;cover=new ImageView(a);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setBackground(Glass.surface(0x4020272B,0x227C8A90,12));cover.setClipToOutline(true);put(head,cover,10,8,96,96);title=text("",24,0xFFF3F5F7);title.setGravity(Gravity.TOP);title.setMaxLines(2);title.setLineSpacing(0,1f);title.setEllipsize(android.text.TextUtils.TruncateAt.END);put(head,title,126,36,350,72);state=text("正在播放",20,0xFFB5C5C2);state.setSingleLine(true);state.setEllipsize(android.text.TextUtils.TruncateAt.END);put(head,state,126,5,350,27);head.setOnClickListener(v->activity.showPlayer());head.setOnFocusChangeListener((v,on)->{title.setTextColor(on?0xFF1C2A2F:0xFFF3F5F7);state.setTextColor(on?0xFF455B62:0xFFB5C5C2);});put(this,head,8,8,492,112);
        toggle=button("暫停",ControlGlyph.PAUSE,()->MediaQueueService.command(a,"TOGGLE"));toggleGlyph=(ControlGlyph)toggle.getCompoundDrawables()[0];put(this,toggle,12,140,150,46);stop=button("停止",ControlGlyph.STOP,()->MediaQueueService.stopPlayback(a));put(this,stop,178,140,150,46);TextView list=button("清單",ControlGlyph.LIST,a::showQueue);put(this,list,344,140,150,46);
        open.setNextFocusDownId(toggle.getId());open.setNextFocusRightId(list.getId());toggle.setNextFocusRightId(stop.getId());stop.setNextFocusLeftId(toggle.getId());stop.setNextFocusRightId(list.getId());list.setNextFocusLeftId(stop.getId());for(View v:new View[]{toggle,stop,list}){v.setNextFocusUpId(open.getId());v.setNextFocusDownId(v.getId());}
        toggle.setNextFocusDownId(stop.getId());stop.setNextFocusDownId(list.getId());list.setNextFocusUpId(stop.getId());stop.setNextFocusUpId(toggle.getId());
    }
    void start(){if(started)return;started=true;images=new FeedRepository(activity);queue.listen(changed);render();}
    void stop(){started=false;queue.unlisten(changed);ui.removeCallbacks(expiry);if(images!=null){images.close();images=null;}}
    void underControls(boolean hidden){hiddenByControls=hidden;setVisibility(showing&&!hidden?VISIBLE:GONE);}
    boolean showing(){return showing;}
    private void render(){if(!started)return;ui.removeCallbacks(expiry);MediaItem current=queue.current();boolean audio=current!=null&&current.provider.equals("podcast");boolean active=audio&&(queue.state.equals("playing")||queue.state.equals("paused")||queue.state.equals("preparing"));if(active)last=current;long until=queue.stoppedAt+30000;boolean tail=last!=null&&queue.stoppedAt>0&&SystemClock.uptimeMillis()<until;boolean visible=active||tail;
        if(showing!=visible){showing=visible;activity.playerDockChanged(visible);}setVisibility(visible&&!hiddenByControls?VISIBLE:GONE);if(!visible)return;MediaItem item=active?current:last;title.setText(QueueDialog.displayTitle(item.title));open.setContentDescription(item.title+"，開啟播放器");state.setText(queue.state.equals("playing")?"正在播放 · "+item.show:queue.state.equals("paused")?"已暫停":queue.state.equals("preparing")?"正在準備音源…":"已停止 · 30 秒後收起");boolean playing=queue.state.equals("playing");toggle.setText(playing?"暫停":"播放");toggle.setContentDescription(playing?"暫停 Podcast":"播放 Podcast");toggleGlyph.mode(playing?ControlGlyph.PAUSE:ControlGlyph.PLAY);if(images!=null&&!loaded.equals(item.id)){loaded=item.id;cover.setImageDrawable(null);images.thumbnail(item.image,b->{if(started&&last!=null&&last.id.equals(item.id))cover.setImageBitmap(b);});}if(tail&&!active)ui.postDelayed(expiry,Math.max(1,until-SystemClock.uptimeMillis()));if(active)HdmiPreview.muteActive();}
    private StateListDrawable focus(int fill){return focus(fill,1000);}
    private StateListDrawable focus(int fill,float radius){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},Glass.surface(0xFFF1F4F5,0xB2DEE7E8,radius));d.addState(new int[]{},Glass.surface(fill,(fill>>>24)==0?0:0x337C8A90,radius));return d;}
    private TextView text(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextColor(color);t.setTextSize(TypedValue.COMPLEX_UNIT_PX,size);t.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));t.setIncludeFontPadding(false);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
    private TextView button(String value,int kind,Runnable action){TextView t=text(value,21,0xFFE6ECEE);t.setId(View.generateViewId());t.setFocusable(true);t.setClickable(true);t.setDefaultFocusHighlightEnabled(false);t.setGravity(Gravity.CENTER);t.setPadding(15,0,15,0);ControlGlyph glyph=new ControlGlyph(kind,0xFFE6ECEE);glyph.setBounds(0,0,19,19);t.setCompoundDrawables(glyph,null,null,null);t.setCompoundDrawablePadding(7);t.setBackground(focus(0x344B555A));t.setOnFocusChangeListener((v,on)->{int color=on?0xFF1C2A2F:0xFFE6ECEE;t.setTextColor(color);glyph.setTint(color);});t.setOnClickListener(v->action.run());return t;}
    /** Small static vector glyphs keep playback symbols aligned with their labels. */
    private static final class ControlGlyph extends Drawable {
        static final int PLAY=0,PAUSE=1,STOP=2,LIST=3;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final Path triangle=new Path();private int kind;
        ControlGlyph(int kind,int color){this.kind=kind;paint.setColor(color);triangle.moveTo(8,4);triangle.lineTo(20,12);triangle.lineTo(8,20);triangle.close();}
        void mode(int value){if(kind!=value){kind=value;invalidateSelf();}}
        @Override public void draw(Canvas canvas){Rect b=getBounds();int save=canvas.save();canvas.translate(b.left,b.top);canvas.scale(b.width()/24f,b.height()/24f);paint.setStyle(Paint.Style.FILL);if(kind==PLAY)canvas.drawPath(triangle,paint);else if(kind==PAUSE){canvas.drawRoundRect(6,4,10,20,1,1,paint);canvas.drawRoundRect(14,4,18,20,1,1,paint);}else if(kind==STOP)canvas.drawRoundRect(5,5,19,19,2,2,paint);else{for(int y=6;y<=18;y+=6){canvas.drawCircle(4,y,1.5f,paint);canvas.drawRoundRect(9,y-1,21,y+1,1,1,paint);}}canvas.restoreToCount(save);}
        @Override public void setTint(int color){paint.setColor(color);invalidateSelf();}@Override public void setAlpha(int alpha){paint.setAlpha(alpha);invalidateSelf();}@Override public void setColorFilter(ColorFilter filter){paint.setColorFilter(filter);invalidateSelf();}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}
    }
    private void put(FrameLayout p,View v,int x,int y,int w,int h){FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(w,h);lp.leftMargin=x;lp.topMargin=y;p.addView(v,lp);}
}
